<?php
declare(strict_types=1);
require_once __DIR__ . '/api/core/App.php';
$admin = require_role('administrador','superadministrador');
$pdo = db();
// The coordinator sees pending opportunities and controls publication; companies retain ownership of their content.
$pending = $pdo->query("SELECT o.id_oportunidad,o.titulo,o.descripcion,o.requisitos,o.ubicacion,o.modalidad,o.tipo_practica,o.remuneracion,o.moneda,o.vacantes,o.fecha_inicio,o.fecha_fin,o.fecha_limite_postulacion,COALESCE(NULLIF(o.estado,''),'pendiente_revision') AS estado,COALESCE(e.nombre_comercial,e.nombre_legal) AS empresa FROM oportunidades o JOIN empresas e ON e.id_empresa=o.id_empresa WHERE o.estado='pendiente_revision' OR o.estado='' OR o.estado IS NULL ORDER BY o.id_oportunidad")->fetchAll();
$opportunities = $pdo->query("SELECT o.id_oportunidad,o.titulo,COALESCE(NULLIF(o.estado,''),'pendiente_revision') AS estado,o.fecha_limite_postulacion,COALESCE(e.nombre_comercial,e.nombre_legal) AS empresa FROM oportunidades o JOIN empresas e ON e.id_empresa=o.id_empresa WHERE COALESCE(o.estado,'')<>'borrado' ORDER BY o.id_oportunidad DESC")->fetchAll();
$pendingCompanies = $pdo->query("SELECT e.id_empresa,e.nombre_legal,e.nombre_comercial,e.sector,e.correo_contacto,u.nombres,u.apellidos,u.correo FROM empresas e JOIN usuarios u ON u.id_usuario=e.id_usuario WHERE u.estado='pendiente' ORDER BY e.id_empresa")->fetchAll();
$applications = $pdo->query("SELECT p.id_postulacion,p.fecha_postulacion,ep.codigo AS estado,o.titulo AS oportunidad,COALESCE(e.nombre_comercial,e.nombre_legal) AS empresa,u.nombres,u.apellidos,u.correo FROM postulaciones p JOIN estados_postulacion ep ON ep.id_estado=p.id_estado JOIN oportunidades o ON o.id_oportunidad=p.id_oportunidad JOIN empresas e ON e.id_empresa=o.id_empresa JOIN estudiantes est ON est.id_estudiante=p.id_estudiante JOIN usuarios u ON u.id_usuario=est.id_usuario WHERE ep.codigo<>'borrado' ORDER BY p.fecha_postulacion DESC")->fetchAll();
$audit = $pdo->query('SELECT b.id_bitacora,b.fecha_evento,b.accion,b.tabla_afectada,b.id_registro,b.datos_anteriores,b.datos_nuevos,b.ip_origen,CONCAT(u.nombres," ",u.apellidos) AS actor FROM bitacora b LEFT JOIN usuarios u ON u.id_usuario=b.id_usuario ORDER BY b.id_bitacora DESC LIMIT 100')->fetchAll();
page_start('Administración');
echo '<section class="page-heading"><div><span class="eyebrow">REVISIÓN DE COORDINACIÓN</span><h1>Administración</h1><p>Aprueba empresas, revisa oportunidades y controla las convocatorias.</p></div><div class="admin-stats"><div><strong>'.count($pending).'</strong><span>oportunidades por revisar</span></div><div><strong>'.count($pendingCompanies).'</strong><span>empresas por aprobar</span></div></div></section>';
echo '<section class="panel company-review" id="empresas"><div class="panel-heading"><div><span class="eyebrow">ACCESO EMPRESARIAL</span><h2>Empresas pendientes</h2></div></div>';
if (!$pendingCompanies) echo '<p class="empty-inline">No hay empresas pendientes.</p>'; else foreach ($pendingCompanies as $c) echo '<article class="company-review-card"><div><strong>'.h($c['nombre_comercial']?:$c['nombre_legal']).'</strong><span>'.h($c['nombres'].' '.$c['apellidos']).' · '.h($c['correo']).' · '.h($c['correo_contacto']).'</span><small>'.h($c['sector']?:'Sector no indicado').'</small></div><form method="post" action="'.h(app_url('api/empresas.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_empresa" value="'.h($c['id_empresa']).'"><input type="hidden" name="decision" value="aprobar"><button class="button button-primary">Aprobar empresa</button></form></article>';
echo '</section><section class="panel" id="oportunidades"><div class="panel-heading"><div><span class="eyebrow">MODERACIÓN</span><h2>Oportunidades enviadas por empresas</h2></div><span class="result-count">'.count($pending).' pendientes</span></div>';
if (!$pending) echo '<p class="empty-inline">No hay oportunidades esperando revisión.</p>';
else foreach ($pending as $o) {
    echo '<article class="company-review-card opportunity-review-card"><div class="opportunity-review-summary"><strong>'.h($o['titulo']).'</strong><span>'.h($o['empresa']).' · '.h($o['modalidad']).' · Cierre '.h($o['fecha_limite_postulacion']).'</span><p>'.h($o['descripcion']).'</p><small>Requisitos: '.h($o['requisitos']?:'No especificados').'</small><a class="button button-quiet" href="'.h(app_url('index.php?id='.$o['id_oportunidad'])).'">Ver oportunidad completa</a></div><form class="opportunity-review-decision" method="post" action="'.h(app_url('api/oportunidades.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_oportunidad" value="'.h($o['id_oportunidad']).'"><label for="revision-comment-'.h($o['id_oportunidad']).'">Comentario para la empresa <span class="optional">(obligatorio al pedir cambios o rechazar)</span></label><textarea id="revision-comment-'.h($o['id_oportunidad']).'" name="comentario_revision" maxlength="2000" rows="3" placeholder="Ejemplo: cambia la remuneración a Q 2,500 y actualiza la fecha de inicio."></textarea><div class="review-actions"><button class="button button-primary" name="decision" value="publicar">Aceptar y publicar</button><button class="button button-quiet" name="decision" value="solicitar_cambios">Solicitar cambios</button><button class="text-danger" name="decision" value="rechazar">Rechazar</button></div></form></article>';
}
echo '</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CONVOCATORIAS</span><h2>Oportunidades registradas</h2></div></div><div class="table-wrap"><table><thead><tr><th>Oportunidad</th><th>Estado</th><th>Fecha límite</th><th>Acción</th></tr></thead><tbody>';
foreach ($opportunities as $o) { $stateLabels=['pendiente_revision'=>'En espera de revisión','requiere_cambios'=>'Cambios solicitados','borrador'=>'Borrador','publicada'=>'Publicada','rechazada'=>'Rechazada','pausada'=>'Pausada','cerrada'=>'Cerrada','borrado'=>'Borrada']; echo '<tr><td>'.h($o['titulo']).'<small>'.h($o['empresa']).'</small></td><td><span class="status-pill">'.h($stateLabels[$o['estado']]??'En espera de revisión').'</span></td><td>'.h($o['fecha_limite_postulacion']).'</td><td><a class="button button-small button-quiet" href="'.h(app_url('index.php?id='.$o['id_oportunidad'])).'">Revisar</a>'; if ($o['estado']==='publicada') echo ' <form method="post" action="'.h(app_url('api/oportunidades.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_oportunidad" value="'.h($o['id_oportunidad']).'"><input type="hidden" name="decision" value="cerrar"><button class="text-danger">Cerrar convocatoria</button></form>'; echo '</td></tr>'; }
echo '</tbody></table></div></section>';
echo '<section class="panel" id="postulaciones"><div class="panel-heading"><div><span class="eyebrow">SEGUIMIENTO GENERAL</span><h2>Postulaciones</h2></div><span class="result-count">'.count($applications).' solicitudes</span></div><div class="table-wrap"><table><thead><tr><th>Estudiante</th><th>Empresa y oportunidad</th><th>Estado</th><th>Actualización</th></tr></thead><tbody>';
foreach($applications as $a) echo '<tr><td>'.h($a['nombres'].' '.$a['apellidos']).'<small>'.h($a['correo']).'</small></td><td>'.h($a['empresa']).'<small>'.h($a['oportunidad']).'</small></td><td>'.h($a['estado']).'</td><td><form method="post" action="'.h(app_url('api/postulaciones.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_postulacion" value="'.h($a['id_postulacion']).'"><select name="estado" required><option value="en_revision">En revisión</option><option value="entrevista">Entrevista</option><option value="aceptada">Aceptada</option><option value="rechazada">Rechazada</option></select><button class="button button-small button-primary">Guardar</button></form></td></tr>';
echo '</tbody></table></div></section>';
echo '<section class="panel" id="bitacora"><div class="panel-heading"><div><span class="eyebrow">TRAZABILIDAD</span><h2>Bitácora reciente</h2><p>Últimos 100 cambios guardados con instantánea JSON e IP de origen.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha y actor</th><th>Acción</th><th>Registro</th><th>Antes → después</th><th>IP</th></tr></thead><tbody>';
foreach($audit as $event) echo '<tr><td>'.h($event['fecha_evento']).'<small>'.h($event['actor']?:'Sistema').'</small></td><td>'.h($event['accion']).'</td><td>'.h($event['tabla_afectada']).' #'.h($event['id_registro']).'</td><td><small>'.h($event['datos_anteriores']?:'—').'</small><small>'.h($event['datos_nuevos']?:'—').'</small></td><td>'.h($event['ip_origen']?:'—').'</td></tr>';
echo '</tbody></table></div></section>';
page_end();

